def lib2to3_parse(
    src_txt: str, target_versions: Collection[TargetVersion] = ()
) -> Node:
    """Given a string with source, return the lib2to3 Node."""
    if not src_txt.endswith("\n"):
        src_txt += "\n"

    grammars = get_grammars(set(target_versions))
    if target_versions:
        max_tv = max(target_versions, key=lambda tv: tv.value)
        tv_str = f" for target version {max_tv.pretty()}"
    else:
        tv_str = ""

    errors = {}
    for grammar in grammars:
        drv = driver.Driver(grammar)
        try:
            result = drv.parse_string(src_txt, False)
            break

        except ParseError as pe:
            lineno, column = pe.context[1]
            lines = src_txt.splitlines()
            try:
                faulty_line = lines[lineno - 1]
            except IndexError:
                faulty_line = "<line number missing in source>"
            error_msg = (
                            f"Cannot parse{tv_str}: {lineno}:{column}\n"
                            f"    {faulty_line}\n"
                            f"    {' ' * (column - 1)}^\n"
                                "SyntaxError: invalid syntax"
                        )

            errors[grammar.version] = InvalidInput(error_msg)

        except TokenError as te:
            # In edge cases these are raised; and typically don't have a "faulty_line".
            lineno, column = te.args[1]
            error_msg = (
                            f"Cannot parse{tv_str}: {lineno}:{column}\n"
                            f"    {te.args[0]}\n"
                            f"    {' ' * (column - 1)}^\n"
                                "SyntaxError: invalid syntax"
                        )

        errors[grammar.version] = InvalidInput(error_msg)

    else:
        # Choose the latest version when raising the actual parsing error.
        assert len(errors) >= 1
        exc = errors[max(errors)]
        raise exc from None

    if isinstance(result, Leaf):
        result = Node(syms.file_input, [result])
    return result

